    [property: Required] string VeranstaltungId,
    [property: Required, MinLength(1)] string Name,
    [property: Required, EmailAddress] string Email,
    [property: Required, MinLength(1)] List<BuchungPositionRequestDto> Sitzplaetze
);

public record BuchungPositionResponseDto(
    string Reihe,
    int Spalte,
    string PreiskategorieId,
    string PreiskategorieName,
    decimal Preis
);

public record BuchungResponseDto(
    string Referenz,
    string Name,
    string Email,
    string Status,
    DateTime ErstelltAm,
    string VeranstaltungId,
    string VeranstaltungTitel,
    DateTime VeranstaltungZeitpunkt,
    string SpielstaetteName,
    string RaumName,
    IReadOnlyList<BuchungPositionResponseDto> Positionen,
    decimal Gesamtpreis
);

