import { chromium } from 'playwright';

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
});
page.on('pageerror', (err) => errors.push(String(err)));

await page.goto('http://localhost:4200/veranstaltungen', { waitUntil: 'networkidle' });
await page.waitForSelector('.veranstaltungs-karte');
await page.screenshot({ path: '/tmp/01-liste.png', fullPage: true });

const erstesEvent = page.locator('.veranstaltungs-karte').first();
const titel = await erstesEvent.locator('.titel').textContent();
console.log('Erstes Event:', titel);
await erstesEvent.click();

await page.waitForSelector('h1');
await page.screenshot({ path: '/tmp/02-detail.png', fullPage: true });

await page.click('text=Sitzplätze auswählen');
await page.waitForSelector('app-sitzplan button.sitz--frei');
await page.screenshot({ path: '/tmp/03-sitzplan.png', fullPage: true });

const freierSitz = page.locator('app-sitzplan button.sitz--frei').first();
await freierSitz.click();
await page.waitForSelector('.auswahl-tabelle');
await page.screenshot({ path: '/tmp/04-auswahl.png', fullPage: true });

await page.fill('input[name="name"]', 'Erika Mustermann');
await page.fill('input[name="email"]', 'erika@example.com');
await page.click('button[type="submit"]');

await page.waitForURL('**/buchungen/*');
await page.waitForSelector('.positionen-tabelle');
await page.screenshot({ path: '/tmp/05-buchung.png', fullPage: true });

console.log('URL nach Buchung:', page.url());
console.log('Konsolenfehler:', errors);

await browser.close();

